    class NoPythonLoader(yaml.Loader):
        def __init__(self, stream):
            super().__init__(stream)

        def construct_scalar(self, node):
            if isinstance(node, yaml.ScalarNode) and node.tag == 'tag:yaml.org,2002:python/object':
                raise yaml.YAMLError("Python objects are not allowed in this YAML.")
            return super().construct_scalar(node)

    return yaml.load(config_data, Loader=NoPythonLoader)
