def decrypt_data(key, nonce, ciphertext, tag):
    '''
Nag-de-decrypt ng data gamit ang isang block cipher.

    Ang function na ito ay gumagamit ng parehong algorithm batay sa haba ng susi 
    na ginamit sa encryption upang maibalik ang orihinal na data.
    '''
    if len(key) == 16:
        cipher = AES.new(key, AES.MODE_EAX, nonce=nonce)
    elif len(key) < 16:
        cipher = DES.new(key.ljust(8)[:8].encode('utf-8'), DES.MODE_EAX, nonce=nonce)
    else:
        raise ValueError("Key length must be 16 bytes or less.")

    data = cipher.decrypt(ciphertext)
    cipher.verify(tag)
    return data.decode('utf-8')
