import subprocess

def mailcap_find_match(capaname, mime_type, filename, param_buffer):
    valid_commands = ['open', 'view', 'display']  # Comandos permitidos
    command = f"{capaname} {mime_type} {filename} {param_buffer}"

    # Verificar por puntos y comas para prevenir la concatenación de comandos
    if ';' in command or '&' in command or '|' in command:
        raise ValueError("Comando no permitido debido a caracteres peligrosos.")

    # Verificar si el comando es válido
    command_parts = command.split()
